/*
 * 一次性清理脚本，内容故意不再改动。
 *
 * 站点第一次部署时开启了 PWA 离线缓存，浏览器里会注册一个把首页和样式都缓存起来的
 * Service Worker。它的脚本文件本身不随内容更新，所以浏览器不会去刷新缓存，
 * 结果就是回头访问的人一直看到旧页面，连新的 HTML 都拿不到。
 *
 * 这里把 /sw.min.js 换成一段用完即走的代码：清空所有缓存，注销自己，然后让页面重新加载。
 * 浏览器只有在发现这个文件变了才会执行更新，所以这段代码必须留在仓库里。
 * 站点现在已经不再注册任何 Service Worker（_config.yml 里 pwa.enabled 为 false），
 * 因此它只会对装过旧版本缓存的浏览器生效一次。
 */
self.addEventListener('install', function () {
  self.skipWaiting();
});

self.addEventListener('activate', function (event) {
  event.waitUntil(
    (async function () {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));

      await self.registration.unregister();

      const clients = await self.clients.matchAll({ type: 'window' });
      for (const client of clients) {
        client.navigate(client.url);
      }
    })()
  );
});
